package com.bank.boundedcontext.deposits;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Deposits context: HERE, "account" means a deposit account with a balance.
public class DepositAccount {
    private static final Logger log = Logger.getLogger(DepositAccount.class.getName());
    private final String id;
    private final String holderName;
    private BigDecimal balance;

    public DepositAccount(String id, String holderName, BigDecimal balance) {
            this.id = id;
            this.holderName = holderName
            this.balance = balance;
    }
    public FundsDebitedEvent debit(BigDecimal amount) {
        balance = balance.subtract(amount);
        log.info(() -> "Deposits: debited " + amount + " from " + id + " → " + balance);
        return new FundsDebitedEvent(id, amount);
    }
    public BigDecimal getBalance() { return balance; }
}
