package com.bank.boundedcontext.lending;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Lending context: HERE, "account" means a loan with principal + EMI.
public class LoanAccount {
    private static final Logger log = Logger.getLogger(LoanAccount.class.getName());
    private final String loanId;
    private final String borrowerName;
    private BigDecimal outstandingPrincipal;
    private final BigDecimal emiAmount;

    public LoanAccount(String loanId, String borrowerName, BigDecimal principal, BigDecimal emi) {
            this.loanId = loanId;
            this.borrowerName = borrowerName;
            this.outstandingPrincipal = principal;
            this.emiAmount = emi;
    }
    public void applyEmiPayment(BigDecimal amount) {
        outstandingPrincipal = outstandingPrincipal.subtract(amount);
        log.info(() -> "Lending: EMI " + amount + " applied to " + loanId
                     + " → outstanding " + outstandingPrincipal);
    }
    public BigDecimal getEmiAmount() { return emiAmount; }
    public BigDecimal getOutstandingPrincipal() { return outstandingPrincipal; }
}
