package com.bank.boundedcontext.lending;

import com.bank.boundedcontext.deposits.FundsDebitedEvent;
import java.util.logging.Logger;

// ANTI-CORRUPTION LAYER: translates a Deposits event into Lending terms,
// so the Deposits model never leaks into the Lending context.
public class DepositAntiCorruptionLayer {
    private static final Logger log = Logger.getLogger(DepositAntiCorruptionLayer.class.getName());
    private final LoanAccount loanAccount;

    public DepositAntiCorruptionLayer(LoanAccount loanAccount) { this.loanAccount = loanAccount; }

    public void onFundsDebited(FundsDebitedEvent event) {
        log.info(() -> "ACL: translating deposit event for " + event.depositAccountId()
                     + " into an EMI payment");
        loanAccount.applyEmiPayment(event.amount());   // Lending's own language
    }
}
