package com.bank.boundedcontext;

import com.bank.boundedcontext.deposits.DepositAccount;
import com.bank.boundedcontext.deposits.FundsDebitedEvent;
import com.bank.boundedcontext.lending.DepositAntiCorruptionLayer;
import com.bank.boundedcontext.lending.LoanAccount;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class BoundedContextDemo {
    private static final Logger log = Logger.getLogger(BoundedContextDemo.class.getName());

    public static void main(String[] args) {
        // Same person, TWO contexts, TWO different "account" models.
        DepositAccount savings = new DepositAccount("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        LoanAccount loan = new LoanAccount("LOAN9001", "Rajesh Kumar",
                new BigDecimal("5000000"), new BigDecimal("45000"));
        DepositAntiCorruptionLayer acl = new DepositAntiCorruptionLayer(loan);

        log.info("=== Auto-debit EMI across bounded contexts ===");
        BigDecimal emi = loan.getEmiAmount();
        FundsDebitedEvent event = savings.debit(emi);   // Deposits context acts + publishes
        acl.onFundsDebited(event);                       // Lending context reacts via ACL

        log.info("Deposit balance now: " + savings.getBalance());
        log.info("Loan outstanding now: " + loan.getOutstandingPrincipal());
    }
}
